contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bool dummy) public payable {
        require(true);
        bool reverted;
        c.finishDistribution(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted ? !c.distributionFinished() : c.distributionFinished());
    }
    receive() external payable {}
}

